//! `mappings::resample` against C's `astResample<X>` with nearest-neighbour
//! and linear interpolation, for every pixel type: 1-D, 2-D and 3-D grids,
//! linear and non-linear Mappings, linear fits, subdivision, simplified and
//! blocked outputs, bad pixels, `no_bad`, variances and an output region.
//! Each case compares the number of bad pixels and every output value and
//! variance, through a hash of their bit patterns, with a sample of values
//! to show where a mismatch is.
//!
//! `resample_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/resample_probe.c`, which documents the input data.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[allow(clippy::excessive_precision)]
#[path = "resample_oracle/cases.rs"]
mod cases;

use ast_core::mappings::{
    DynMapping, Interp, MathMap, PermMap, ResampleFlags, ResampleInput, ResampleOptions,
    ResampleOutput, ShiftMap, UnitMap, WinMap, ZoomMap, resample,
};
use ast_core::pixel::PixelValue;

fn mapping(name: &str) -> DynMapping {
    match name {
        "unit2" => Box::new(UnitMap::new(2)),
        "shift_half" => Box::new(ShiftMap::new(vec![0.5, -0.25])),
        "zoom2" => Box::new(ZoomMap::new(2, 1.7).unwrap()),
        "perm" => Box::new(PermMap::new(&[2, 1], &[2, 1], &[]).unwrap()),
        "nonlin2" => Box::new(
            MathMap::new(
                2,
                2,
                &["p=a", "q=b"],
                &["a=p+0.02*p*q-0.3", "b=q-0.015*p*p+0.2"],
            )
            .unwrap(),
        ),
        "cubic1" => Box::new(MathMap::new(1, 1, &["p=a"], &["a=0.001*p*p*p+0.5*p"]).unwrap()),
        "win3" => Box::new(
            WinMap::from_corners(
                &[0.0, 0.0, 0.0],
                &[1.0, 1.0, 1.0],
                &[0.3, -0.2, 0.1],
                &[1.1, 0.7, 1.4],
            )
            .unwrap(),
        ),
        "nonlin3" => Box::new(
            MathMap::new(
                3,
                3,
                &["p=a", "q=b", "r=c"],
                &["a=p+0.05*q*r", "b=q-0.03*p*p", "c=0.9*r+0.1*p"],
            )
            .unwrap(),
        ),
        "noinverse" => Box::new(MathMap::new(2, 2, &["p=a", "q=b"], &["a", "b"]).unwrap()),
        _ => panic!("no Mapping {name}"),
    }
}

/// A pixel value from a double, as C's cast.
trait FromF64: PixelValue {
    fn from_f64(v: f64) -> Self;
}

macro_rules! from_f64 {
    ($($t:ty),*) => {$(
        impl FromF64 for $t {
            fn from_f64(v: f64) -> Self {
                v as $t
            }
        }
    )*};
}
from_f64!(f64, f32, i64, u64, i32, u32, i16, u16, i8, u8);

fn npix(l: &[i64], u: &[i64]) -> usize {
    l.iter().zip(u).map(|(l, u)| (u - l + 1) as usize).product()
}

/// Run one case for pixel type `T`, returning (bad pixels, hash, samples).
fn run<T: FromF64>(c: &cases::Case) -> (usize, u64, Vec<f64>) {
    let &(
        _,
        map,
        _,
        _,
        lbnd_in,
        ubnd_in,
        lbnd_out,
        ubnd_out,
        lbnd,
        ubnd,
        interp,
        use_bad,
        no_bad,
        use_var,
        _,
        tol,
        maxpix,
        ..,
    ) = c;
    let nin = npix(lbnd_in, ubnd_in);
    let nout = npix(lbnd_out, ubnd_out);
    let (mut data, mut var) = (Vec::with_capacity(nin), Vec::with_capacity(nin));
    for k in 0..nin as i64 {
        let (mut d, mut v) = if T::FLOATING {
            (
                T::from_f64(((7 * k) % 97) as f64 * 0.37 - 10.0),
                T::from_f64(((3 * k) % 11) as f64 * 0.5 - 1.0),
            )
        } else {
            let (ds, vs) = if T::SIGNED { (40, 2) } else { (0, 0) };
            (
                T::from_f64(((7 * k) % 97 - ds) as f64),
                T::from_f64(((3 * k) % 11 - vs) as f64),
            )
        };
        if use_bad && k % 17 == 3 {
            d = T::from_f64(120.0);
        }
        if use_bad && k % 19 == 5 {
            v = T::from_f64(120.0);
        }
        data.push(d);
        var.push(v);
    }
    let mut out = vec![T::from_f64(77.0); nout];
    let mut out_var = vec![T::from_f64(77.0); nout];
    let m = mapping(map);
    let nbad = resample(
        m.as_ref(),
        &ResampleInput {
            lbnd: lbnd_in,
            ubnd: ubnd_in,
            data: &data,
            var: use_var.then_some(&var[..]),
        },
        &mut ResampleOutput {
            lbnd: lbnd_out,
            ubnd: ubnd_out,
            region_lbnd: lbnd,
            region_ubnd: ubnd,
            data: &mut out,
            var: use_var.then_some(&mut out_var[..]),
        },
        &ResampleOptions {
            interp: if interp == "nearest" {
                Interp::Nearest
            } else {
                Interp::Linear
            },
            params: &[],
            flags: ResampleFlags { use_bad, no_bad },
            tol,
            maxpix,
        },
        T::from_f64(120.0),
    )
    .unwrap();
    let mut hash: u64 = 14695981039346656037;
    for k in 0..nout {
        hash = (hash ^ out[k].to_f64().to_bits()).wrapping_mul(1099511628211);
        if use_var {
            hash = (hash ^ out_var[k].to_f64().to_bits()).wrapping_mul(1099511628211);
        }
    }
    let samples = out.iter().step_by(211).map(|v| v.to_f64()).collect();
    (nbad, hash, samples)
}

#[test]
fn resampling_matches_c() {
    let mut failures = Vec::new();
    for c in cases::CASES {
        let (name, ty, want_nbad, status, want_hash, want_samples) =
            (c.0, c.2, c.17, c.18, c.19, c.20);
        assert_eq!(status, 0, "{name} {ty}: C reported an error");
        let (nbad, hash, samples) = match ty {
            "D" => run::<f64>(c),
            "F" => run::<f32>(c),
            "L" => run::<i64>(c),
            "UL" => run::<u64>(c),
            "I" => run::<i32>(c),
            "UI" => run::<u32>(c),
            "S" => run::<i16>(c),
            "US" => run::<u16>(c),
            "B" => run::<i8>(c),
            "UB" => run::<u8>(c),
            _ => panic!("no type {ty}"),
        };
        if nbad != want_nbad || hash != want_hash || samples != want_samples {
            failures.push(format!(
                "{name} {ty}: bad {nbad} want {want_nbad}; hash {}; samples\n  got  {samples:?}\n  want {want_samples:?}",
                if hash == want_hash { "same" } else { "differs" }
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} cases differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn errors_match_c() {
    let input: Vec<f64> = (0..400).map(f64::from).collect();
    let mut out = vec![0.0_f64; 400];
    let (l2, u2, bad, rl, ru) = (
        [1_i64, 1],
        [10_i64, 10],
        [11_i64, 1],
        [0_i64, 1],
        [10_i64, 11],
    );
    let run = |map: &str,
               lbnd_in: &[i64],
               ubnd_in: &[i64],
               lbnd_out: &[i64],
               ubnd_out: &[i64],
               region: (&[i64], &[i64]),
               tol: f64,
               out: &mut [f64]| {
        let n = npix(lbnd_in, ubnd_in).min(400);
        resample(
            mapping(map).as_ref(),
            &ResampleInput {
                lbnd: lbnd_in,
                ubnd: ubnd_in,
                data: &input[..n],
                var: None,
            },
            &mut ResampleOutput {
                lbnd: lbnd_out,
                ubnd: ubnd_out,
                region_lbnd: region.0,
                region_ubnd: region.1,
                data: out,
                var: None,
            },
            &ResampleOptions {
                interp: Interp::Linear,
                params: &[],
                flags: ResampleFlags::default(),
                tol,
                maxpix: 50,
            },
            -1.0,
        )
        .unwrap_err()
        .code() as i32
    };
    let o = &mut out[..100];
    let codes = [
        run("unit2", &l2[..1], &u2[..1], &l2, &u2, (&l2, &u2), 0.0, o),
        run(
            "unit2",
            &l2,
            &u2,
            &[1, 1, 1],
            &[10, 10, 10],
            (&[1, 1, 1], &[10, 10, 10]),
            0.0,
            o,
        ),
        run("unit2", &bad, &u2, &l2, &u2, (&l2, &u2), 0.0, o),
        run("unit2", &l2, &u2, &bad, &u2, (&l2, &u2), 0.0, o),
        run("unit2", &l2, &u2, &l2, &u2, (&rl, &u2), 0.0, o),
        run("unit2", &l2, &u2, &l2, &u2, (&l2, &ru), 0.0, o),
        run("unit2", &l2, &u2, &l2, &u2, (&l2, &u2), -1.0, o),
        run("noinverse", &l2, &u2, &l2, &u2, (&l2, &u2), 0.0, o),
    ];
    assert_eq!(codes, cases::ERRORS);
}
